async function saveLibrary(e){e.preventDefault();if(!['ADMIN','CALIDAD'].includes(account?.role))return;const f=new FormData(e.currentTarget);const code=String(f.get('code')||'').trim().toUpperCase();const title=String(f.get('title')||'').trim();const version=String(f.get('version')||'').trim();const responsible=String(f.get('responsible')||'').trim();const type=libraryDraft.internal55?'INTERNO_CONSULTA':libraryDraft.external51?'EXTERNO':String(f.get('type')||'').trim();const classification=String(f.get('classification')||'');const area=String(f.get('area')||'GESTION');const url=String(f.get('url')||'').trim();if(url){try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw Error();}catch{setErr('Utilice una dirección HTTP o HTTPS válida.');return;}}
const file=f.get('file');if((libraryDraft.external51||libraryDraft.internal55)&&(!file||!file.size||file.type!=='application/pdf')){setErr('Para el expediente legal 5.1 debe seleccionar el PDF oficial del documento externo.');return;}if(file?.size>600*1024){setErr('El PDF supera 600 KB.');return;}setLibraryBusy(true);try{const localText=await readLocalReference(file?.size?file:null);const text=[code,title,String(f.get('description')||''),file?.name||'',localText].join(' ');const suggested=suggestRequirements(text);const selected=[...new Set([...(type==='EXTERNO'?[]:suggested),...(libraryDraft.requirementIds||[])])];if((libraryDraft.external51||libraryDraft.internal55)&&libraryItems.some(x=>x.type==='EXTERNO'&&x.title?.trim().toLowerCase()===title.toLowerCase()))throw Error('Ya existe un documento con este título en Biblioteca. Revíselo y vincúlelo desde 5.1 para evitar duplicados.');const existing=libraryItems.find(x=>x.code?.toUpperCase()===code);if(existing){if(libraryDraft.external51||libraryDraft.internal55)throw Error('Ya existe ese código. Use «Vincular» para reutilizar el documento, o «Nueva edición» desde su expediente.');if(!file?.size)throw Error('El código ya existe. Abra Consultar para agregar una edición PDF.');await storePdfVersion(existing,file,version,user.uid);setLibraryModal(false);setLibraryDraft({});setErr('PDF incorporado a '+code+'. Abra Consultar para visualizarlo.');return;}
await createLibraryEntry({code,title,version,responsible,type,classification,area,description:String(f.get('description')||'').slice(0,500),referenceUrl:url,referenceFileName:file?.size?file.name:'',fileStored:false,requirementIds:selected},user.uid);if(file?.size)await storePdfVersion({id:libraryCodeId(code)},file,version,user.uid);setLibraryModal(false);setLibraryDraft({});setErr('Documento registrado en el Centro Documental. Abra Consultar para preparar su revisión.');}catch(ex){setErr(ex?.code==='permission-denied'?'Firebase rechazó el guardado: permisos insuficientes. Compruebe que las reglas publicadas sean las del ZIP y que su usuario tenga rol ADMIN o CALIDAD. '+ex.message:ex.message)}finally{setLibraryBusy(false)}}
async function archivePG0204Template(){
 if(!user||!['ADMIN','CALIDAD'].includes(account?.role))throw Error('Solo Calidad o Administración pueden archivar la plantilla.');
 const code='PG0204', version='04', id=libraryCodeId(code);
 const response=await fetch('/PSI-PG0204-04_PLANTILLA_PROPUESTA.pdf');
 if(!response.ok)throw Error('No se pudo obtener la plantilla PDF.');
 const blob=await response.blob();
 const file=new File([blob],'PSI-PG0204-04_PLANTILLA_PROPUESTA.pdf',{type:'application/pdf'});
 const existing=libraryItems.find(d=>String(d.code||'').toUpperCase()===code);
 if(existing){
  if(String(existing.version)===version&&existing.fileStored)throw Error('PG0204-04 ya está archivado. Consulte su expediente en Biblioteca; no se generó un duplicado.');
  if(String(existing.version)===version&&!existing.fileStored){await storePdfVersion(existing,file,version,user.uid);}
  else {if(!window.confirm('PG0204 ya existe en Biblioteca. ¿Registrar la edición 04 propuesta como nueva edición, conservando las anteriores?'))return;await storePdfVersion(existing,file,version,user.uid);}
 }else{
  await createLibraryEntry({code,title:'Acta de Difusión',version,responsible:'Coordinación de Calidad',type:'FORMATO',classification:'FORMATO',area:'GESTION',description:'Plantilla institucional propuesta de difusión y comunicación del SGC; requiere aprobación 8.3.',referenceUrl:'',referenceFileName:'',fileStored:false,requirementIds:['5.7','8.3']},user.uid);
  await storePdfVersion({id},file,version,user.uid);
 }
 setErr('Plantilla PG0204-04 archivada como REGISTRADA, pendiente de revisión y aprobación en 8.3.');
 setPage('biblioteca');
}
