async function openPdf(item){setApprovalNote('');listLibraryApprovalEvents(item).then(setApprovalEvents).catch(()=>setApprovalEvents([]));setPdfTab('documento');setNewEdition(false);setSignedFile(null);setSignedConfirm(false);setPdfViewer({item,url:null});setPdfLoading(true);try{const versions=await listPdfVersions(item);setPdfVersions(versions);if(versions.length){const chosen=versions.find(v=>v.version===item.version)||versions[0];const url=await previewPdf(item,chosen.version,chosen.version===item.version?item.activePdfId:null);setPdfViewer({item,url,version:chosen.version});}}catch(e){setErr(e.message)}finally{setPdfLoading(false)}}
