async function approvalAction(action){if(!pdfViewer)return;setApprovalBusy(true);try{if(action==='APPROVE'){if(!user?.email||!signPassword||!signConfirm)throw Error('Confirme su identidad y la decisión de aprobación.');await reauthenticateWithCredential(auth.currentUser,EmailAuthProvider.credential(user.email,signPassword));}await decideLibraryApproval(pdfViewer.item,action,user.uid,account?.role,approvalNote);const fresh={...pdfViewer.item,approvalStatus:action==='REVIEW'?'IN_REVIEW':action==='APPROVE'?'APPROVED':'RETURNED',reviewRequestedBy:action==='REVIEW'?user.uid:pdfViewer.item.reviewRequestedBy,approvalVersion:action==='APPROVE'?pdfViewer.item.version:pdfViewer.item.approvalVersion,decisionNote:approvalNote};setPdfViewer(v=>({...v,item:fresh}));setApprovalEvents(await listLibraryApprovalEvents(fresh));setApprovalNote('');setSignPassword('');setSignConfirm(false);setSignModal(false);setErr(action==='APPROVE'?'Aprobación documental registrada. Consulte la constancia y el historial de decisiones.':'Decisión documental registrada.');}catch(e){setErr('Control documental: '+e.message)}finally{setApprovalBusy(false)}}
async function openCurrentRiskMatrix(){
 const tab=window.open('','_blank');
 if(!tab){setErr('Permita ventanas emergentes para consultar la matriz.');return;}
 tab.document.title='PSI-MC1101-05 · Matriz actualizada';
 tab.document.body.innerHTML='<p style="font:16px Arial;padding:24px">Consultando identificaciones de Firebase…</p>';
 try{
  const records=await listAllRisk1101(user.uid,['ADMIN','CALIDAD'].includes(account?.role));
  if(tab.closed)return;
  const url=URL.createObjectURL(risk1101MatrixPdf(records));
  tab.location.replace(url);
  setTimeout(()=>URL.revokeObjectURL(url),180000);
 }catch(error){if(!tab.closed)tab.document.body.textContent='No se pudo consultar la matriz: '+error.message;setErr(error.message)}
}
function closePdf(){setPdfViewer(old=>{if(old?.url)URL.revokeObjectURL(old.url);return null});setPdfVersions([])}
async function addPdfVersion(item,file,version){if(!file)return;setPdfLoading(true);try{await storePdfVersion(item,file,version,user.uid);setPdfVersions(await listPdfVersions(item));const url=await previewPdf(item,version,version===item.version?item.activePdfId:null);setPdfViewer(old=>{if(old?.url)URL.revokeObjectURL(old.url);return {item:{...item,version,fileStored:true},url,version};});setErr('PDF guardado correctamente.');}catch(e){setErr(e?.code==='permission-denied'?'Firebase rechazó la carga. Revise las reglas publicadas y el rol ADMIN/CALIDAD. '+e.message:e.message)}finally{setPdfLoading(false)}}
async function uploadSignedPdf(){if(!pdfViewer?.item||!signedFile)return setErr('Seleccione el PDF firmado.');setSignedBusy(true);try{const item=pdfViewer.item;const id=await replaceWithSignedPdf(item,signedFile,user.uid,signedConfirm);const updated={...item,activePdfId:id,pdfSignatureState:'SIGNED',referenceFileName:signedFile.name};setPdfVersions(await listPdfVersions(updated));const url=await previewPdf(updated,item.version,id);setPdfViewer(old=>{if(old?.url)URL.revokeObjectURL(old.url);return {...old,item:updated,url,version:item.version};});setSignedFile(null);setSignedConfirm(false);setErr('PDF firmado incorporado. Edición conservada y original disponible en historial.');}catch(e){setErr('PDF firmado: '+e.message)}finally{setSignedBusy(false)}}
